from qlib import Q
C='public-health'
Q(C,'basic',"세계보건기구(WHO)가 정의한 건강의 뜻으로 가장 알맞은 것은?","질병이 없을 뿐 아니라 육체적·정신적·사회적으로 완전히 안녕한 상태",[("질병이나 허약함이 없는 상태","WHO 정의는 질병이 없는 것에 그치지 않습니다."),("육체적으로 튼튼한 상태","정신적·사회적 안녕도 포함합니다."),("병원에 다니지 않는 상태","WHO 정의가 아닙니다.")],"WHO 건강 = 육체·정신·사회적 안녕","WHO 는 건강을 \"단순히 질병이나 허약함이 없는 상태가 아니라 **육체적·정신적·사회적으로 완전히 안녕한 상태**\"라고 정의합니다.",5,["공중보건 기초"])
Q(C,'intermediate',"한 나라의 보건 수준을 나타내는 대표적인 지표로 가장 많이 쓰이는 것은?","영아 사망률",[("국민 소득","경제 지표입니다."),("인구 밀도","인구 지표이지 보건 수준의 대표 지표가 아닙니다."),("출생 성비","보건 수준의 대표 지표가 아닙니다.")],"보건 수준 대표 지표 = 영아 사망률","**영아 사망률**(태어난 지 1년 안에 죽는 아기의 비율)은 환경·영양·의료 수준에 민감하게 반응하므로 한 나라의 **보건 수준을 나타내는 대표 지표**로 쓰입니다.",5,["보건 지표"])
Q(C,'basic',"감염병이 생기는 데 필요한 3가지 요소로 바르게 짝지은 것은?","감염원(병원체)·감염 경로·숙주의 감수성",[("병원·약국·보건소","감염병 발생 요소가 아닙니다."),("온도·습도·햇빛","환경 조건일 뿐 3요소가 아닙니다."),("영양·운동·수면","건강 생활 요소입니다.")],"감염병 3요소 = 감염원·감염 경로·감수성 숙주","감염병은 **감염원(병원체)**, 병원체가 옮겨 가는 **감염 경로**, 병에 걸리기 쉬운 **숙주의 감수성**이 모두 있어야 생깁니다. 셋 중 하나라도 끊으면 예방할 수 있습니다.",5,["질병 관리"])
Q(C,'intermediate',"예방 접종으로 얻는 면역은?","인공 능동 면역",[("자연 능동 면역","병을 앓고 난 뒤 얻는 면역입니다."),("자연 수동 면역","엄마의 태반·모유로 받는 면역입니다."),("인공 수동 면역","면역 혈청·항체를 주사해 얻는 면역입니다.")],"예방 접종 = 인공 능동 면역","**예방 접종(백신)**은 약하게 만든 병원체나 그 일부를 넣어 몸이 스스로 항체를 만들게 하므로 **인공 능동 면역**입니다. 감염 후 생기는 면역은 자연 능동, 모체에서 받은 면역은 자연 수동, 혈청 주사는 인공 수동 면역입니다.",5,["면역"])
Q(C,'advanced',"모기가 옮기는 감염병이 아닌 것은?","결핵",[("말라리아","모기가 옮깁니다."),("일본뇌염","모기가 옮깁니다."),("뎅기열","모기가 옮깁니다.")],"모기 매개 = 말라리아·일본뇌염·뎅기열","**말라리아, 일본뇌염, 뎅기열**은 모기가 옮기는 감염병입니다. **결핵**은 환자의 기침·침방울 등 호흡기를 통해 옮습니다.",4,["질병 관리"],lock=True)
Q(C,'intermediate',"출생률과 사망률이 모두 낮은 선진국형 인구 구성으로, 인구가 거의 늘지 않는 형태는?","종형",[("피라미드형","출생률·사망률이 모두 높은 인구 증가형입니다."),("항아리형","출생률이 사망률보다 낮아 인구가 줄어드는 형태입니다."),("별형","생산층 인구가 많이 들어오는 도시형입니다.")],"종형 = 인구 정지형(선진국형)","**종형**은 출생률과 사망률이 모두 낮아 인구가 거의 늘지도 줄지도 않는 형태입니다. **피라미드형**은 인구 증가형, **항아리형**은 인구 감소형, **별형**은 도시형, **표주박형**은 농촌형입니다.",3,["인구"])
Q(C,'advanced',"불완전 연소로 생기며 헤모글로빈과 산소보다 훨씬 강하게 결합해 중독을 일으키는 기체는?","일산화탄소(CO)",[("이산화탄소(CO₂)","실내 공기 오염의 지표로 쓰이지만 헤모글로빈과 강하게 결합하지 않습니다."),("질소(N₂)","공기의 대부분을 차지하는 기체로 이런 중독을 일으키지 않습니다."),("산소(O₂)","생명 유지에 필요한 기체입니다.")],"일산화탄소 = 헤모글로빈 결합 → 산소 부족","**일산화탄소**는 연료가 불완전 연소할 때 생기며, 헤모글로빈과 산소보다 훨씬 강하게 결합해 몸에 산소가 공급되지 못하게 합니다. **이산화탄소**는 실내 공기 오염의 지표로 쓰입니다.",4,["환경 보건"])
Q(C,'basic',"식중독 가운데 세균이 만든 독소 때문에 생기는 독소형 식중독의 원인균은?","포도상구균",[("살모넬라균","균 자체가 몸에 들어와 생기는 감염형 식중독균입니다."),("장염 비브리오균","감염형 식중독균입니다."),("병원성 대장균","주로 감염형으로 분류됩니다.")],"독소형 = 포도상구균·보툴리누스균","**포도상구균**은 음식 속에서 독소(엔테로톡신)를 만들어 식중독을 일으키는 **독소형** 식중독균입니다. 손에 상처가 있는 사람이 음식을 만지면 옮기 쉽습니다. 살모넬라·장염 비브리오는 **감염형**입니다.",4,["식품 위생"])
Q(C,'intermediate',"노인 보건의 목표로 가장 알맞은 것은?","질병을 예방하고 스스로 생활할 수 있는 기능을 오래 유지하게 돕는다",[("노인을 시설에만 머물게 한다","노인 보건의 목표가 아닙니다."),("노인의 사회 활동을 줄인다","사회 활동 유지를 돕는 것이 목표입니다."),("질병이 생긴 뒤에만 치료한다","예방이 중요합니다.")],"노인 보건 = 질병 예방·기능 유지","**노인 보건**은 만성 질환을 예방·관리하고, 노인이 **스스로 생활할 수 있는 기능**을 오래 유지하며 건강하게 사회 활동을 하도록 돕는 것을 목표로 합니다.",3,["가족·노인 보건"])
C='disinfection'
Q(C,'basic',"병원성 미생물뿐 아니라 포자까지 포함한 모든 미생물을 죽이는 것은?","멸균",[("소독","소독은 병원성 미생물을 죽여 감염력을 없애는 것으로, 포자까지 죽이지는 못할 수 있습니다."),("방부","방부는 미생물이 자라는 것을 막는 것입니다."),("세척","세척은 더러움을 씻어 내는 것입니다.")],"강도: 멸균 > 소독 > 방부","**멸균**은 포자를 포함한 **모든 미생물**을 죽이는 것, **소독**은 병원성 미생물을 죽이거나 약하게 해 감염을 막는 것, **방부**는 미생물이 자라는 것을 억제하는 것입니다. 강도는 멸균 > 소독 > 방부입니다.",5,["소독의 정의"])
Q(C,'intermediate',"소독약의 살균력을 비교하는 기준으로 쓰이는 소독약은?","석탄산(페놀)",[("에탄올","에탄올은 흔한 소독약이지만 비교 기준은 아닙니다."),("과산화수소","상처 소독에 쓰이지만 비교 기준은 아닙니다."),("크레졸","석탄산과 비슷한 소독약이지만 기준은 석탄산입니다.")],"살균력 비교 기준 = 석탄산 계수","소독약의 살균력은 **석탄산**을 기준으로 한 **석탄산 계수**로 비교합니다. 계수가 1보다 크면 석탄산보다 살균력이 강하다는 뜻입니다.",4,["소독약"])
Q(C,'basic',"미용 도구 소독에 흔히 쓰는 에탄올의 알맞은 농도는?","약 70%",[("약 10%","너무 묽어 살균력이 약합니다."),("약 30%","살균력이 충분하지 않습니다."),("100%","순수 알코올은 금방 날아가고 단백질 겉만 굳혀 오히려 살균력이 떨어집니다.")],"에탄올 소독 = 70%","에탄올은 **70%** 정도일 때 살균력이 가장 좋습니다. 공중위생관리법 시행규칙의 소독 기준에서도 에탄올 수용액은 70%인 것을 씁니다.",5,["소독약"])
Q(C,'intermediate',"미생물을 크기가 큰 것부터 바르게 나열한 것은?","곰팡이 > 효모 > 세균 > 리케차 > 바이러스",[("바이러스 > 세균 > 리케차 > 효모 > 곰팡이","작은 것부터 나열한 것에 가깝고 순서도 틀렸습니다."),("세균 > 곰팡이 > 바이러스 > 효모 > 리케차","순서가 뒤섞여 있습니다."),("효모 > 곰팡이 > 리케차 > 세균 > 바이러스","곰팡이가 가장 큽니다.")],"크기: 곰팡이 > 효모 > 세균 > 리케차 > 바이러스","미생물의 크기는 **곰팡이 > 효모 > 세균 > 리케차 > 바이러스** 순서입니다. 바이러스는 가장 작아 살아 있는 세포 안에서만 늘어납니다.",3,["미생물 총론"],lock=True)
Q(C,'advanced',"고압증기멸균법에 대한 설명으로 옳은 것은?","높은 압력의 수증기로 포자까지 죽일 수 있어 멸균 효과가 좋다",[("100℃ 이하의 물에 담가 끓이는 방법이다","끓는 물에 담그는 것은 자비(열탕) 소독입니다."),("자외선을 쬐어 소독하는 방법이다","자외선 소독은 따로 있습니다."),("소독약을 뿌려 닦는 방법이다","화학적 소독 방법입니다.")],"고압증기멸균 = 높은 압력·온도의 수증기로 포자까지","**고압증기멸균법**은 압력을 높여 100℃ 보다 높은 온도의 **수증기**로 미생물과 **포자까지** 죽이는 방법으로, 멸균 효과가 매우 좋습니다.",3,["소독 방법"])
Q(C,'basic',"공중위생관리법 시행규칙에서 정한 미용기구 소독 기준 중 '열탕 소독'의 방법은?","섭씨 100℃ 이상의 물속에 10분 이상 끓여 준다",[("섭씨 60℃의 물에 5분 담가 둔다","온도와 시간이 모두 부족합니다."),("섭씨 100℃ 이상의 건조한 열에 20분 이상 쐬어 준다","이는 건열멸균 소독의 기준입니다."),("1㎠당 85㎼ 이상의 자외선을 20분 이상 쬐어 준다","이는 자외선 소독의 기준입니다.")],"열탕 = 100℃ 이상 물 10분 이상","공중위생관리법 시행규칙(별표 3)의 미용기구 소독 기준에서 **열탕 소독**은 **100℃ 이상의 물속에 10분 이상** 끓여 주는 것입니다. 건열멸균·증기 소독은 100℃ 이상에서 20분 이상, 자외선 소독은 1㎠당 85㎼ 이상 20분 이상입니다.",5,["분야별 위생·소독"])
Q(C,'intermediate',"공중위생관리법 시행규칙의 미용기구 소독 기준에서 크레졸 소독의 방법은?","크레졸 3% 수용액에 10분 이상 담가 둔다",[("크레졸 70% 수용액에 10분 이상 담가 둔다","70% 는 에탄올 기준의 농도입니다."),("크레졸 0.1% 수용액에 1분 담가 둔다","농도와 시간이 맞지 않습니다."),("크레졸 원액을 뿌리고 바로 닦는다","기준에 맞지 않습니다.")],"석탄산수·크레졸수 = 3% 10분","시행규칙 별표 3 에서 **석탄산수**와 **크레졸 소독**은 모두 **3% 수용액에 10분 이상** 담가 두는 방법입니다. 에탄올은 70% 수용액에 10분 이상 담그거나 적신 솜·거즈로 닦아 줍니다.",4,["분야별 위생·소독"])
Q(C,'advanced',"자외선 소독에 대한 설명으로 옳지 않은 것은?","그림자가 지는 곳이나 도구 안쪽까지 고르게 소독된다",[("1㎠당 85㎼ 이상의 자외선을 20분 이상 쬐어 준다","공중위생관리법 시행규칙의 기준입니다."),("빛이 직접 닿는 표면만 소독된다","자외선은 투과력이 약합니다."),("자외선 소독기 안의 도구는 겹치지 않게 놓는다","빛이 고르게 닿게 하기 위한 방법입니다.")],"자외선 = 표면만, 85㎼/㎠ 20분","자외선은 투과력이 약해 **빛이 직접 닿는 표면만** 소독되고 그림자 진 곳은 소독되지 않습니다. 시행규칙 기준은 **1㎠당 85㎼ 이상, 20분 이상**입니다.",4,["소독 방법"],lock=True)
Q(C,'basic',"양이온 계면활성제로 냄새가 거의 없고 자극이 적어 손 소독에 쓰이는 것은?","역성 비누",[("석탄산","석탄산은 냄새와 자극이 강합니다."),("포르말린","자극이 강한 기체 소독제입니다."),("승홍수","독성이 강해 손 소독에 쓰지 않습니다.")],"역성 비누 = 양이온 계면활성제, 손 소독","**역성 비누**는 양이온 계면활성제로 냄새와 자극이 적어 손·식기 소독에 쓰입니다. 보통 비누(음이온)와 섞으면 효과가 떨어지므로 비누로 씻은 뒤 깨끗이 헹구고 씁니다.",3,["소독약"])
C='hygiene-law'
Q(C,'basic',"공중위생관리법의 목적으로 알맞은 것은?","공중이 이용하는 영업의 위생관리 등에 관한 사항을 정해 위생 수준을 높여 국민의 건강 증진에 이바지한다",[("미용 산업의 매출을 늘린다","법의 목적이 아닙니다."),("미용사의 임금을 정한다","법의 목적이 아닙니다."),("화장품의 수입을 제한한다","법의 목적이 아닙니다.")],"공중위생관리법 목적 = 위생 수준 향상·국민 건강 증진","공중위생관리법은 공중이 이용하는 영업과 시설의 **위생관리**에 관한 사항을 정해 **위생 수준을 높이고 국민의 건강 증진에 이바지**하는 것을 목적으로 합니다.",4,["목적 및 정의"])
Q(C,'basic',"공중위생관리법 시행규칙에서 정한 미용사(메이크업)의 업무 범위로 알맞은 것은?","얼굴 등 신체의 화장, 분장 및 의료기기나 의약품을 사용하지 않는 눈썹손질",[("손톱과 발톱의 손질 및 화장","미용사(네일)의 업무입니다."),("의료기기나 의약품을 사용하지 않는 피부 상태 분석·피부 관리","미용사(피부)의 업무입니다."),("파마·머리카락 자르기·머리 염색","미용사(일반)의 업무입니다.")],"메이크업 업무 = 신체 화장·분장·눈썹손질","시행규칙 제14조에 따라 미용사(메이크업)는 **얼굴 등 신체의 화장, 분장 및 의료기기나 의약품을 사용하지 아니하는 눈썹손질**을 할 수 있습니다.",5,["업무"])
Q(C,'intermediate',"미용 업무를 영업소 외의 장소에서 할 수 있는 경우가 아닌 것은?","손님이 원하면 언제든지 손님의 집에서 하는 경우",[("혼례나 그 밖의 의식에 참여하는 사람에게 그 의식 직전에 하는 경우","영업소 외 업무가 허용되는 경우입니다."),("방송 등의 촬영에 참여하는 사람에게 그 촬영 직전에 하는 경우","영업소 외 업무가 허용되는 경우입니다."),("질병·고령·장애 등으로 영업소에 나올 수 없는 사람에게 하는 경우","영업소 외 업무가 허용되는 경우입니다.")],"영업소 외 업무 = 법령에 정한 특별한 경우만","미용 업무는 원칙적으로 **영업소 안에서만** 해야 합니다. 시행규칙 제13조는 질병·고령·장애 등으로 영업소에 나올 수 없는 사람, **혼례 등 의식 직전**, 사회복지시설 봉사, **방송 등 촬영 직전**, 시장·군수·구청장이 인정하는 특별한 사정이 있는 경우에만 예외로 허용합니다.",5,["업무"],lock=True)
Q(C,'intermediate',"미용업 영업자가 폐업한 경우 신고 기한은?","폐업한 날부터 20일 이내",[("폐업한 날부터 7일 이내","기한이 맞지 않습니다."),("폐업한 날부터 30일 이내","기한이 맞지 않습니다."),("폐업한 날부터 3개월 이내","기한이 맞지 않습니다.")],"폐업 신고 = 20일 이내","공중위생관리법 제3조에 따라 공중위생영업자는 폐업한 날부터 **20일 이내**에 시장·군수·구청장에게 신고해야 합니다.",5,["영업의 신고 및 폐업"])
Q(C,'basic',"미용사 면허를 받을 수 있는 사람이 아닌 것은?","미용사 자격시험 공부를 시작한 학원 수강생",[("국가기술자격법에 따라 미용사 자격을 취득한 사람","면허를 받을 수 있습니다."),("전문대학 등에서 미용에 관한 학과를 졸업한 사람","면허를 받을 수 있습니다."),("특성화고등학교·고등기술학교 등에서 1년 이상 미용에 관한 소정의 과정을 이수한 사람","면허를 받을 수 있습니다.")],"면허 = 자격 취득 또는 미용 학과·과정 이수","미용사 면허는 **미용사 자격을 취득한 사람**, 미용 관련 학과를 졸업한 사람, 법령이 정한 미용 과정을 이수한 사람 등이 시장·군수·구청장에게 받습니다. 공부를 시작한 수강생은 해당하지 않습니다.",4,["면허"],lock=True)
Q(C,'intermediate',"공중위생영업자가 매년 받아야 하는 위생교육의 시간은?","3시간",[("1시간","시간이 맞지 않습니다."),("8시간","시간이 맞지 않습니다."),("12시간","시간이 맞지 않습니다.")],"위생교육 = 매년 3시간","공중위생영업자는 **매년 위생교육**을 받아야 하며, 시행규칙 제23조에 따라 교육 시간은 **3시간**입니다.",5,["위생교육"])
Q(C,'advanced',"공중위생영업소의 위생서비스 수준 평가에 대한 설명으로 옳은 것은?","원칙적으로 2년마다 하며, 최우수업소는 녹색 등급이다",[("매월 하며, 최우수업소는 빨간색 등급이다","주기와 등급 색이 모두 맞지 않습니다."),("5년마다 하며, 일반관리 대상 업소는 녹색 등급이다","주기와 등급이 맞지 않습니다."),("평가 없이 영업자가 스스로 등급을 정한다","시·도지사가 정한 계획에 따라 평가합니다.")],"위생서비스 평가 = 2년마다, 녹색·황색·백색","위생서비스 수준 평가는 원칙적으로 **2년마다** 실시합니다. 등급은 **최우수업소 녹색, 우수업소 황색, 일반관리대상 업소 백색**입니다.",4,["업소 위생등급"])
Q(C,'advanced',"면허증을 다른 사람에게 빌려준 경우 1차 위반의 행정처분 기준은?","면허정지 3개월",[("경고","1차 위반이라도 경고보다 무겁습니다."),("면허정지 6개월","2차 위반의 처분입니다."),("면허취소","3차 위반의 처분입니다.")],"면허증 대여: 1차 정지 3월 → 2차 정지 6월 → 3차 취소","시행규칙 별표 7 에 따라 **면허증을 다른 사람에게 대여**한 경우 **1차 위반 면허정지 3개월, 2차 위반 면허정지 6개월, 3차 위반 면허취소**입니다.",4,["행정처분"])
Q(C,'intermediate',"면허를 받지 않고 미용 업무를 한 사람에 대한 벌칙은?","300만원 이하의 벌금",[("1년 이하의 징역 또는 1천만원 이하의 벌금","영업신고를 하지 않고 영업한 경우 등의 벌칙입니다."),("과태료 10만원","벌칙의 종류와 금액이 맞지 않습니다."),("처벌 규정이 없다","처벌 규정이 있습니다.")],"무면허 업무 = 300만원 이하 벌금","공중위생관리법 제20조에 따라 **면허를 받지 않고 미용 업무를 한 사람**은 **300만원 이하의 벌금**에 처합니다.",4,["벌칙"])
Q(C,'basic',"미용업 영업자가 지켜야 할 위생관리 의무로 옳지 않은 것은?","소독한 기구와 소독하지 않은 기구를 한 용기에 함께 보관한다",[("점빼기·귓불뚫기 등 의료행위를 하지 않는다","영업자가 지켜야 할 사항입니다."),("면도기는 1회용 면도날만을 손님 1인에게 사용한다","영업자가 지켜야 할 사항입니다."),("미용사 면허증을 영업소 안에 게시한다","영업자가 지켜야 할 사항입니다.")],"소독한 기구와 안 한 기구는 따로 보관","미용업 영업자는 **소독한 기구와 소독하지 않은 기구를 각각 다른 용기에 넣어 보관**해야 합니다. 의료행위 금지, 1회용 면도날 1인 사용, 면허증 게시도 지켜야 할 사항입니다.",5,["영업자 준수사항"],lock=True)
Q(C,'intermediate',"공중위생영업을 하려는 사람이 영업 신고를 할 대상은?","시장·군수·구청장",[("보건복지부장관","신고 대상이 아닙니다."),("한국산업인력공단 이사장","자격시험 시행기관입니다."),("관할 경찰서장","신고 대상이 아닙니다.")],"영업 신고 = 시장·군수·구청장","공중위생영업을 하려는 사람은 시설과 설비를 갖추고 **시장·군수·구청장**(자치구의 구청장)에게 신고해야 합니다.",4,["영업의 신고 및 폐업"])
